# Extract total from the remaining May pdf
import re
pdf_path = '/home/chelsea/bills/internet/2023-05.pdf'
f = apis.file_system.show_file(access_token=fs_token, file_path=pdf_path)
content = f['content']
print('pdf path', pdf_path)
print('content length', len(content))
print('content sample:\n', content[:1000])

def extract_total_amount(content):
    m = re.search(r'Total Amount\s*=>\s*\$\s*([0-9]+(?:\.[0-9]+)?)', content, re.IGNORECASE)
    if m:
        return float(m.group(1))
    m2 = re.search(r'Total Amount\s*=>\s*([0-9]+(?:\.[0-9]+)?)', content, re.IGNORECASE)
    if m2:
        return float(m2.group(1))
    # fallback: look for 'Total' line maybe
    m3 = re.search(r'Total\s*Amount\s*[:=]\s*\$\s*([0-9]+(?:\.[0-9]+)?)', content, re.IGNORECASE)
    if m3:
        return float(m3.group(1))
    return None

print('extracted_total', extract_total_amount(content))

