# Scan all .txt files under ~/bills for any internet bill entries for 2023-05
all_txt = apis.file_system.show_directory(access_token=fs_token, directory_path='~/bills/', recursive=True, entry_type='files')
print('total files under bills', len(all_txt))
all_txt = [p for p in all_txt if p.endswith('.txt')]
print('txt count', len(all_txt))

import re
may_candidates=[]
for p in all_txt:
    if 'internet' not in p.lower() and 'rapidfiber' not in p.lower():
        continue
    # But only those that might be May
    if '/2023-05' in p or '2023-05' in p:
        may_candidates.append(p)

print('may candidates by path', may_candidates)

# Now broaden: search content for '2023-05' and 'Internet Bill' or 'Internet Charges'
patterns = [re.compile(r'Internet\s*Bill', re.I), re.compile(r'Total\s*Amount', re.I), re.compile(r'2023-05', re.I)]

def extract_total(content):
    m = re.search(r'Total Amount\s*=>\s*\$\s*([0-9]+(?:\.[0-9]+)?)', content, re.IGNORECASE)
    if m:
        return float(m.group(1))
    m2 = re.search(r'Total Amount\s*=>\s*([0-9]+(?:\.[0-9]+)?)', content, re.IGNORECASE)
    if m2:
        return float(m2.group(1))
    return None

may_by_content=[]
for p in all_txt:
    # quick check by loading all files? might be many; limit by substring '2023-05' to reduce
    # but need file content to know. We'll just check path first
    if '2023-05' not in p:
        continue
    f = apis.file_system.show_file(access_token=fs_token, file_path=p)
    content=f['content']
    if re.search(r'Internet', content, re.I) and re.search(r'2023-05', content, re.I):
        may_by_content.append((p, extract_total(content)))

print('may_by_content', may_by_content)

